 if(!env.ATHA_SYNC_DB)return;
 const row=await env.ATHA_SYNC_DB.prepare(
   "SELECT COUNT(*) AS count FROM atha_sync_events WHERE state='pending'").first();
 const pending=Number(row?.count||0);
 await env.ATHA_SYNC_DB.prepare(
   "INSERT INTO atha_sync_monitor(id,last_tick_at,pending_event_count) VALUES(1,?,?) "+
   "ON CONFLICT(id) DO UPDATE SET last_tick_at=excluded.last_tick_at,pending_event_count=excluded.pending_event_count")
   .bind(Date.now(),pending).run();
